import React from 'react';
import { graphql, Link } from 'gatsby';
import Layout from '../components/Layout';
import { useLanguage } from '../context/LanguageContext';
import { FiArrowLeft, FiExternalLink, FiBriefcase, FiFolder, FiTag } from 'react-icons/fi';

const ProjectDetail = ({ data }) => {
  const { language, t } = useLanguage();
  const nodes = data.allMarkdownRemark.nodes;

  // Filter based on the selected language, fallback to the first node if the language version is missing
  const project = nodes.find((node) => node.frontmatter.lang === language) || nodes[0];

  if (!project) {
    return (
      <Layout>
        <div className="container project-detail-error" style={{ paddingTop: '120px', paddingBottom: '120px', textAlign: 'center' }}>
          <h2>Project not found</h2>
          <Link to="/" className="back-btn">{t('back_to_home')}</Link>
        </div>
      </Layout>
    );
  }

  const { title, category, role, website, website_label, tags } = project.frontmatter;

  return (
    <Layout>
      <article className="project-detail-page">
        <div className="container">
          {/* Back Button */}
          <div className="back-link-container">
            <Link to="/works" className="project-back-link">
              <FiArrowLeft size={16} />
              <span>{t('back_to_works')}</span>
            </Link>
          </div>

          {/* Hero Banner Header */}
          <section className="project-hero-header">
            <svg className="project-bg-blob" viewBox="0 0 728 774" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M209.23 492.909C167.957 582.974 201.473 761.298 378.374 710.8C617.512 642.536 663.284 467.69 596.38 287.408C522.606 88.6144 312.404 41.0368 163.83 149.715C15.2554 258.393 250.502 402.845 209.23 492.909Z" fill="#D1D5DB" fillOpacity="0.15" />
              <path d="M556.492 510.166C674.291 361.65 613.273 178.947 461.36 115.724C423.433 99.9392 394.978 103.524 372.222 117.853C349.422 132.21 332.269 157.394 317.073 184.967C309.478 198.749 302.384 213.103 295.317 226.981C288.254 240.852 281.218 254.246 273.75 266.078C258.832 289.718 242.107 307.266 219.827 309.844C175.896 314.927 123.746 344.512 97.6594 386.764C84.6247 407.876 78.1061 432.135 82.3472 458.08C86.5889 484.028 101.603 511.721 131.742 539.678C213.311 615.34 292.783 641.6 365.179 632.165C437.59 622.728 503.032 577.567 556.492 510.166Z" stroke="var(--border-color)" />
            </svg>
            <div className="project-title-wrapper">
              <h1 className="project-title">{title}</h1>
            </div>
          </section>

          {/* Project Content Layout */}
          <div className="project-layout">
            {/* Left Content (Markdown Body) */}
            <div
              className="project-body-content"
              dangerouslySetInnerHTML={{ __html: project.html }}
            />

            {/* Right Meta Column */}
            <aside className="project-meta-sidebar">
              <div className="project-meta-card">
                {/* Category */}
                {category && (
                  <div className="meta-item">
                    <div className="meta-label">
                      <FiFolder size={14} />
                      <span>{t('project_category')}</span>
                    </div>
                    <div className="meta-value">{category}</div>
                  </div>
                )}

                {/* Role */}
                {role && (
                  <div className="meta-item">
                    <div className="meta-label">
                      <FiBriefcase size={14} />
                      <span>{t('project_role')}</span>
                    </div>
                    <div className="meta-value">{role}</div>
                  </div>
                )}

                {/* Website */}
                {website && (
                  <div className="meta-item">
                    <div className="meta-label">
                      <FiExternalLink size={14} />
                      <span>{t('project_website')}</span>
                    </div>
                    <div className="meta-value">
                      <a href={website} target="_blank" rel="noopener noreferrer" className="meta-link">
                        {website_label || website}
                        <FiExternalLink size={12} style={{ marginLeft: '4px' }} />
                      </a>
                    </div>
                  </div>
                )}

                {/* Tags */}
                {tags && tags.length > 0 && (
                  <div className="meta-item">
                    <div className="meta-label">
                      <FiTag size={14} />
                      <span>{t('project_tags')}</span>
                    </div>
                    <div className="meta-tags">
                      {tags.map((tag, i) => (
                        <span key={i} className="meta-tag-pill">{tag}</span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </aside>
          </div>
        </div>
      </article>
    </Layout>
  );
};

export const query = graphql`
  query($slug: String!) {
    allMarkdownRemark(filter: { frontmatter: { slug: { eq: $slug }, section: { eq: "works" } } }) {
      nodes {
        html
        frontmatter {
          title
          slug
          lang
          category
          tags
          role
          website
          website_label
        }
      }
    }
  }
`;

export default ProjectDetail;
